def generate(output=Path('assets/items')):
    output=Path(output)
    output.mkdir(parents=True,exist_ok=True)
    for slug,record in SPRITES.items():
        pal=record['palette']
        colors=['#'+pal[i:i+6] for i in range(0,len(pal),6)]
        packed=zlib.decompress(base64.b85decode(record['data']))
        assert len(packed)==512,(slug,len(packed))
        pix=[v for byte in packed for v in (byte>>4,byte&15)]
        runs=[]
        for y in range(32):
            x=0
            while x<32:
                index=pix[y*32+x]
                if not index:
                    x+=1
                    continue
                start=x
                while x<32 and pix[y*32+x]==index:x+=1
                runs.append(f'<rect x="{start}" y="{y}" width="{x-start}" height="1" fill="{colors[index]}"/>')
        svg='<svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 32 32" shape-rendering="crispEdges">'+''.join(runs)+'</svg>'
        (output/(slug+'.svg')).write_text(svg,encoding='utf8')
    print(f'ADVENTURE ODYSSEY ITEM ART: {len(SPRITES)} original-derived icons generated')

if __name__=='__main__':generate()